// The 'open' service: `ctx.open(target)` opens a thing (a file on a server, a URL, a kind of a
// plugin's own) in whichever plugin handles it best, the handlers being the plugins'. A file
// browser opens a file without knowing the editor; the editor registers for text files, a
// browser for URLs (`ctx.open.register({ name, match, open })`).
//
// Resolution: every handler's `match(target)` scores it; those above 0 are the candidates. None:
// undefined. One: it opens the target. Several: the choice remembered for the target's key
// (`file:.ts`, `url:github.com`, `<kind>:*`) if that handler is among them, else an "Open
// with…" popup (`ctx.ui.popup`) listing them best first; the pick is remembered in the store's
// area `open` unless its "Always use" box is unticked. `{ handler }` skips all that (an agent's
// route: `handlers(target)` lists the candidates), `{ ask: true }` asks even so.
//
// The service is callable (cordis' `Service.invoke`): `ctx.open(target, { from })` and
// `ctx.open.register(…)` are the same object. The popup lives in the page, outside every window,
// so `ctx.ui.snapshot()` does not show it; its buttons carry aria-labels and `data-call="open"`
// all the same.
import { Service } from 'cordis'
import type { Context } from 'cordis'
import type { FileTarget, Json, OpenHandler, OpenHandlerRow, OpenOptions, OpenSource, OpenTarget, Popup, StoreArea, TilrPluginClass, UrlTarget } from 'tilr'

/** The store's area of the remembered choices: key (`file:.ts`) → handler id. */
export const AREA = 'open'

/** A registered handler: its id and plugin settled. */
export interface Handler extends OpenHandler {
  id: string
  plugin: string
}

/** A target checked: a 'file' needs `server` and `path`, a 'url' its `url`, every target a
 *  `kind`. Throws on one that is not; returns it as given. */
export function check(target: unknown): OpenTarget {
  const t = target as Record<string, unknown> | null
  if (!t || typeof t !== 'object' || typeof t.kind !== 'string' || !t.kind) throw new Error('open: a target is { kind, … }')
  if (t.kind === 'file' && (typeof t.server !== 'string' || typeof t.path !== 'string' || !t.path)) throw new Error('open: a file target needs `server` and `path` (strings)')
  if (t.kind === 'url' && (typeof t.url !== 'string' || !t.url)) throw new Error('open: a url target needs `url` (a string)')
  return t as OpenTarget
}

/** The last part of a path ('' for '/'). */
export function basename(path: string): string {
  return path.replace(/\/+$/, '').split('/').pop() ?? ''
}

/** A file's extension, lower case with its dot (`.ts`); '' for none (`Makefile`, `.bashrc`). */
export function extension(path: string): string {
  const name = basename(path)
  const dot = name.lastIndexOf('.')
  return dot > 0 ? name.slice(dot).toLowerCase() : ''
}

/** What a remembered choice is kept under: `file:.ts` (`file:` for no extension),
 *  `url:github.com` (the host, lower case; `url:` when it does not parse), `<kind>:*`. */
export function keyOf(target: OpenTarget): string {
  if (target.kind === 'file') return `file:${extension((target as FileTarget).path)}`
  if (target.kind === 'url') {
    try { return `url:${new URL((target as UrlTarget).url).hostname.toLowerCase()}` } catch { return 'url:' }
  }
  return `${target.kind}:*`
}

/** How the "Always use" box names the key: `.ts files`, `files without an extension`,
 *  `github.com`, `issue`. */
export function describeKey(key: string): string {
  const [kind, rest] = [key.slice(0, key.indexOf(':')), key.slice(key.indexOf(':') + 1)]
  if (kind === 'file') return rest ? `${rest} files` : 'files without an extension'
  if (kind === 'url') return rest || 'web addresses'
  return kind
}

/**
 * The handlers and the choice among them, minus cordis and the DOM (the tests drive it
 * directly). `ask` shows the candidates and resolves to the picked one and whether to remember
 * it, or null when dismissed.
 */
export class Registry {
  private handlers = new Map<string, Handler>()
  private store: { get(key: string): Json | undefined, set(key: string, value: Json): void, delete(key: string): void, keys(): string[] }

  constructor(store: Registry['store']) {
    this.store = store
  }

  add(handler: Handler): () => void {
    if (this.handlers.has(handler.id)) throw new Error(`open: a handler "${handler.id}" is already registered`)
    this.handlers.set(handler.id, handler)
    return () => { if (this.handlers.get(handler.id) === handler) this.handlers.delete(handler.id) }
  }

  /** Every handler, in registration order. */
  all(): Handler[] {
    return [...this.handlers.values()]
  }

  /** The handlers that match `target` (score > 0), best first, registration order among equals.
   *  A throwing `match` counts as 0 (and is logged). */
  candidates(target: OpenTarget): { handler: Handler, score: number }[] {
    const out: { handler: Handler, score: number }[] = []
    for (const handler of this.handlers.values()) {
      let score = 0
      try { score = Number(handler.match(target)) || 0 } catch (error) { console.error(`[open] ${handler.id}: match threw`, error) }
      if (score > 0) out.push({ handler, score })
    }
    return out.sort((a, b) => b.score - a.score)
  }

  /** The handler `name` stands for: an id, else the first of that plugin. */
  find(name: string): Handler | undefined {
    return this.handlers.get(name) ?? this.all().find(handler => handler.plugin === name)
  }

  /** The remembered choice for `target`'s key. */
  remembered(target: OpenTarget): string | undefined {
    const id = this.store.get(keyOf(target))
    return typeof id === 'string' ? id : undefined
  }

  /** The handler to open `target` with, or null for none (nothing matches, a choice dismissed). */
  async choose(target: OpenTarget, options: OpenOptions, ask: (candidates: Handler[], key: string) => Promise<{ handler: Handler, remember: boolean } | null>): Promise<Handler | null> {
    if (options.handler !== undefined) {
      const handler = this.find(options.handler)
      if (!handler) throw new Error(`open: no handler "${options.handler}" (open.handlers() lists them)`)
      return handler
    }
    const candidates = this.candidates(target).map(c => c.handler)
    if (!candidates.length) return null
    if (!options.ask) {
      if (candidates.length === 1) return candidates[0]
      const remembered = this.remembered(target)
      const handler = candidates.find(h => h.id === remembered)
      if (handler) return handler
    }
    const key = keyOf(target)
    const picked = await ask(candidates, key)
    if (!picked) return null
    if (picked.remember) this.store.set(key, picked.handler.id)
    return picked.handler
  }

  defaults(): Record<string, string> {
    const out: Record<string, string> = {}
    for (const key of this.store.keys()) {
      const id = this.store.get(key)
      if (typeof id === 'string') out[key] = id
    }
    return out
  }

  forget(key?: string | OpenTarget): void {
    if (key === undefined) for (const k of this.store.keys()) this.store.delete(k)
    else this.store.delete(typeof key === 'string' ? key : keyOf(check(key)))
  }
}

const css = `
  .tilr-open-with {
    position: fixed; z-index: 2147483646; top: 22%; left: 50%; transform: translateX(-50%);
    min-width: 260px; max-width: 420px; padding: 8px; box-sizing: border-box;
    display: flex; flex-direction: column; gap: 2px;
    font: var(--font); color: var(--text);
    background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.35);
  }
  .tilr-open-with[hidden] { display: none; }
  .tilr-open-with h2 {
    margin: 0 0 6px; padding: 0 6px; font: inherit; font-weight: bold; color: var(--muted);
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  }
  .tilr-open-with button {
    display: flex; justify-content: space-between; gap: 16px; padding: 5px 6px;
    font: inherit; color: inherit; text-align: left; background: none; border: 0; border-radius: var(--radius);
    cursor: pointer;
  }
  .tilr-open-with button:hover, .tilr-open-with button:focus-visible { background: var(--line); color: var(--accent); outline: none; }
  .tilr-open-with button span { color: var(--muted); }
  .tilr-open-with label { display: flex; align-items: center; gap: 6px; margin-top: 6px; padding: 0 6px; color: var(--muted); }
`

class OpenService extends Service {
  static provide = 'open'
  static author = 'dan'
  static tags = ['core']
  static version = __TILR_VERSION__
  // ui: the "Open with…" popup; store: the remembered choices.
  static inject = ['ui', 'store']
  // Plugins register their handlers here: switching it off would take every "open" along.
  static locked = true

  declare state: { registry: Registry, popup: Popup, pending: ((picked: { handler: Handler, remember: boolean } | null) => void) | null }

  constructor(ctx: Context) {
    super(ctx, OpenService.provide)
    const area: StoreArea = ctx.store.area(AREA)
    ctx.ui.style(css)
    const element = document.createElement('div')
    element.className = 'tilr-open-with'
    element.setAttribute('role', 'dialog')
    element.setAttribute('aria-label', 'Open with')
    ctx.effect(() => {
      document.body.append(element)
      return () => element.remove()
    }, 'open: the popup')
    const popup = ctx.ui.popup(element)
    this.state = { registry: new Registry(area), popup, pending: null }
    // Closed without a pick (Escape, a press outside): the open resolves to undefined.
    popup.subscribe(opened => { if (!opened) this.settle(null) })
  }

  /** `ctx.open(target, options)`. `this.ctx` is the caller's: the default `from` is its plugin. */
  async [Service.invoke](target: OpenTarget, options: OpenOptions = {}): Promise<string | undefined> {
    check(target)
    const handler = await this.state.registry.choose(target, options ?? {}, (candidates, key) => this.ask(target, candidates, key))
    if (!handler) return undefined
    const from: OpenSource = options?.from ?? { plugin: this.caller(), window: null }
    const id = await handler.open(target, from)
    return typeof id === 'string' ? id : undefined
  }

  register(handler: OpenHandler): () => void {
    if (!handler || typeof handler.name !== 'string' || !handler.name || typeof handler.match !== 'function' || typeof handler.open !== 'function') {
      throw new Error('open.register: { name, match(target), open(target, from) }')
    }
    const plugin = handler.plugin ?? this.caller()
    const entry: Handler = { ...handler, plugin, id: `${plugin}/${handler.name}` }
    // this.ctx is the caller's: the handler leaves with the plugin that registered it.
    let remove: (() => void) | null = null
    const dispose = this.ctx.effect(() => {
      remove = this.state.registry.add(entry)
      return () => remove?.()
    }, `open.register(${entry.id})`)
    return () => { void dispose() }
  }

  handlers(target?: OpenTarget): OpenHandlerRow[] {
    const { registry } = this.state
    if (target === undefined) return registry.all().map(h => ({ id: h.id, plugin: h.plugin, name: h.name }))
    check(target)
    const remembered = registry.remembered(target)
    return registry.candidates(target).map(({ handler: h, score }) => ({
      id: h.id, plugin: h.plugin, name: h.name, score, ...(h.id === remembered ? { default: true as const } : {}),
    }))
  }

  defaults(): Record<string, string> {
    return this.state.registry.defaults()
  }

  forget(key?: string | OpenTarget): void {
    this.state.registry.forget(key)
  }

  /** The calling plugin's name in plugins.json (its fiber's name outside them). */
  private caller(): string {
    const host = this.ctx.root.get('plugins') as { owner?(fiber: unknown): string | null } | undefined
    return host?.owner?.(this.ctx.fiber) ?? (this.ctx.fiber.name || 'tilr')
  }

  /** Shows "Open with…" for `candidates`; resolves to the pick, or null when dismissed (or
   *  another ask took the popup over). */
  private ask(target: OpenTarget, candidates: Handler[], key: string): Promise<{ handler: Handler, remember: boolean } | null> {
    this.settle(null)
    const { popup } = this.state
    const element = popup.element
    const what = target.kind === 'file' ? basename((target as FileTarget).path) : target.kind === 'url' ? (target as UrlTarget).url : target.kind
    const title = document.createElement('h2')
    title.textContent = `Open ${what} with…`
    const remember = document.createElement('input')
    remember.type = 'checkbox'
    remember.checked = true
    const label = document.createElement('label')
    label.append(remember, `Always use it for ${describeKey(key)}`)
    const buttons = candidates.map(handler => {
      const button = document.createElement('button')
      button.type = 'button'
      button.dataset.call = 'open'
      button.dataset.handler = handler.id
      button.setAttribute('aria-label', `Open with ${handler.name}`)
      const name = document.createElement('b')
      name.textContent = handler.name
      const plugin = document.createElement('span')
      plugin.textContent = handler.plugin
      button.append(name, plugin)
      button.addEventListener('click', () => this.settle({ handler, remember: remember.checked }))
      return button
    })
    // Arrows move between the handlers; Enter presses the focused one (a button's own).
    element.onkeydown = event => {
      if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return
      event.preventDefault()
      const at = buttons.indexOf(document.activeElement as HTMLButtonElement)
      const next = (at + (event.key === 'ArrowDown' ? 1 : -1) + buttons.length) % buttons.length
      buttons[next].focus()
    }
    element.replaceChildren(title, ...buttons, label)
    return new Promise(resolve => {
      this.state.pending = resolve
      popup.open()
      buttons[0]?.focus()
    })
  }

  /** Ends the pending ask with `picked` and closes the popup. */
  private settle(picked: { handler: Handler, remember: boolean } | null): void {
    const resolve = this.state.pending
    this.state.pending = null
    resolve?.(picked)
    this.state.popup.close()
  }
}

export default OpenService satisfies TilrPluginClass
